def solve():
    # Read input
    line = input().split()
    N = int(line[0])
    H = int(line[1])
    W = int(line[2])

    tiles = []
    for _ in range(N):
        a, b = map(int, input().split())
        tiles.append((a, b))

    # Total area of the grid
    total_area = H * W

    # Try all possible ways to place tiles (backtracking)
    # We'll use recursion with backtracking to try placing each tile
    # Each tile can be placed as (a, b) or (b, a) due to rotation/flipping

    def can_place(grid, r, c, h, w):
        # Check if the rectangle of size h x w can be placed starting at (r, c)
        if r + h > H or c + w > W:
            return False
        for i in range(h):
            for j in range(w):
                if grid[r + i][c + j] != 0:
                    return False
        return True

    def place_tile(grid, r, c, h, w, tile_id):
        # Place tile of size h x w starting at (r, c)
        for i in range(h):
            for j in range(w):
                grid[r + i][c + j] = tile_id + 1  # Mark with tile ID (1-indexed)

    def remove_tile(grid, r, c, h, w):
        # Remove tile from grid
        for i in range(h):
            for j in range(w):
                grid[r + i][c + j] = 0

    def backtrack(tile_idx, grid):
        # If all tiles are processed, check if entire grid is filled
        if tile_idx == N:
            return all(grid[i][j] != 0 for i in range(H) for j in range(W))

        a, b = tiles[tile_idx]

        # Try both orientations: (a, b) and (b, a)
        orientations = [(a, b), (b, a)]

        for h, w in orientations:
            # Try placing this tile at every possible position
            for r in range(H):
                for c in range(W):
                    if can_place(grid, r, c, h, w):
                        place_tile(grid, r, c, h, w, tile_idx)
                        if backtrack(tile_idx + 1, grid):
                            return True
                        remove_tile(grid, r, c, h, w)

        return False

    # Initialize empty grid
    grid = [[0] * W for _ in range(H)]

    # Check if it's possible to place tiles
    if backtrack(0, grid):
        print("Yes")
    else:
        print("No")

